class Brewer : CoffeeMaker {
    override fun brew(names: List<String>): String {
        if (names.isEmpty()) return render(emptyList())
        val accepted = names.filter { portions(it) > 0 }
        return render(accepted)
    }

    fun retry(attempts: Int): Int {
        if (attempts <= 0) return 0
        return 1 + retry(attempts - 1)
    }

    fun score(batches: List<List<String>>): Int {
        var total = 0
        for (batch in batches) {
            for (name in batch) {
                val amount = portions(name)
                if (amount > 0 && amount <= 3) total += amount
            }
        }
        return total
    }

    // Deliberately exceed the cyclomatic-complexity limit without deep nesting.
    fun classify(amount: Int): Int {
        var category = 0
        if (amount > 0) category++
        if (amount > 1) category++
        if (amount > 2) category++
        if (amount > 3) category++
        if (amount > 4) category++
        if (amount > 5) category++
        if (amount > 6) category++
        if (amount > 7) category++
        return category
    }

    fun ready(water: Int, beans: Int, cups: Int, temperature: Int): Boolean {
        return water > 0 && beans > 0 && cups > 0 && temperature > 0
    }

    fun calibrate(dose: Int, water: Int, seconds: Int, temperature: Int,
                  grind: Int, pressure: Int, humidity: Int, altitude: Int): Int {
        val extraction = water * pressure / maxOf(dose * seconds, 1)
        return extraction + temperature - grind - humidity / 10 + altitude / 100
    }
}

class Inventory(private val available: MutableMap<String, Int> = mutableMapOf()) :
    StockLedger<Inventory.Change>(), Reservable {
    data class Change(val drink: String, val units: Int, val reason: String)

    override fun record(entry: Change) {
        super.record(entry)
        available[entry.drink] = units(entry.drink) + entry.units
    }

    fun receive(vararg shipments: Change) {
        shipments.forEach { record(it) }
    }

    override fun reserve(order: Order): Boolean {
        val needed = mutableMapOf<String, Int>()
        for (line in order.lines) {
            val amount = portions(line.drink) * line.quantity
            if (amount == 0) return false
            needed[line.drink] = (needed[line.drink] ?: 0) + amount
        }
        if (needed.any { (drink, count) -> units(drink) < count }) return false
        needed.forEach { (drink, count) -> record(Change(drink, -count, "order")) }
        return true
    }

    fun units(drink: String): Int = available[drink] ?: 0

    companion object {
        fun stocked(espresso: Int = 40, filter: Int = 60): Inventory {
            val inventory = Inventory()
            inventory.receive(Change("espresso", espresso, "opening"), Change("filter", filter, "opening"))
            return inventory
        }
    }
}

