    companion object {
        fun stocked(espresso: Int = 40, filter: Int = 60): Inventory {
            val inventory = Inventory()
            inventory.receive(Change("espresso", espresso, "opening"), Change("filter", filter, "opening"))
            return inventory
        }
    }
}

